  v_data    jsonb := '[{"subject": "matematika", "title": "Kwadrat funksiýa we onuň grafigi", "topic": "Kwadrat funksiýa", "goal": "Okuwçy a, b, c parametrleriniň parabola täsirini düşündirip, depe nokadyny we kökleri tapyp bilmeli.", "body": "**Kwadrat funksiýa** y = ax² + bx + c görnüşinde ýazylýar, bu ýerde a ≠ 0.\n\nOnuň grafigi **parabola** diýlip atlandyrylýar. a > 0 bolsa şahalary ýokary, a < 0 bolsa aşak gönükdirilýär.\n\nDepe nokadynyň koordinatasy: x = −b / (2a). Simmetriýa oky şol nokatdan geçýär.\n\n**Diskriminant** D = b² − 4ac kökleriň sanyny kesgitleýär: D > 0 — iki kök, D = 0 — bir kök, D < 0 — hakyky kök ýok.", "demo_kind": "function_plot", "demo_config": {"a": 1, "b": -4, "c": 3}, "practical": "Interaktiw görkezmede a = −1, b = 2, c = 3 goýuň. Depe nokadyny, diskriminanty we kökleri ýazyň. Soňra a-ny položitel edip, parabolanyň nähili üýtgändigini düşündiriň.", "test_title": "Kwadrat funksiýa — barlag", "duration": 900, "questions": [{"kind": "choice", "prompt": "y = ax² + bx + c funksiýasynda a > 0 bolsa, parabolanyň şahalary nirä gönükdirilen?", "points": 1, "payload": {"options": [{"id": "a", "text": "Ýokary"}, {"id": "b", "text": "Aşak"}, {"id": "c", "text": "Çepe"}, {"id": "d", "text": "Saga"}]}, "key": {"correct": ["a"]}, "hint": "a-nyň alamatyna serediň.", "explanation": "a > 0 bolanda parabolanyň şahalary ýokary gönükdirilýär."}, {"kind": "choice", "prompt": "Diskriminant D < 0 bolsa, deňlemäniň näçe hakyky köki bar?", "points": 1, "payload": {"options": [{"id": "a", "text": "Hakyky kök ýok"}, {"id": "b", "text": "Bir kök"}, {"id": "c", "text": "Iki kök"}, {"id": "d", "text": "Sonsuz köp"}]}, "key": {"correct": ["a"]}, "explanation": "D < 0 bolanda kwadrat deňlemäniň hakyky köki ýok."}, {"kind": "choice", "prompt": "Parabolanyň depe nokadynyň x koordinatasy haýsy formula bilen tapylýar?", "points": 1, "payload": {"options": [{"id": "a", "text": "x = b / a"}, {"id": "b", "text": "x = −c / b"}, {"id": "c", "text": "x = −b / (2a)"}, {"id": "d", "text": "x = b² − 4ac"}]}, "key": {"correct": ["c"]}, "explanation": "Depe nokady simmetriýa okunda ýerleşýär: x = −b / (2a)."}, {"kind": "numeric", "prompt": "x² − 5x + 6 = 0 deňlemesiniň uly köküni tapyň.", "points": 2, "key": {"value": 3, "tolerance": 0}, "hint": "Wiýet teoremasyny ulanyň.", "explanation": "Kökler: x₁ = 2, x₂ = 3. Uly kök — 3."}, {"kind": "numeric", "prompt": "y = x² − 4x + 3 funksiýasynyň depe nokadynyň x koordinatasyny tapyň.", "points": 2, "key": {"value": 2, "tolerance": 0}, "hint": "x = −b / (2a)", "explanation": "x = −(−4) / (2·1) = 2."}, {"kind": "short", "prompt": "b² − 4ac aňlatmasynyň ady näme?", "points": 1, "key": {"accept": ["diskriminant", "diskriminanty", "D"]}, "explanation": "Bu aňlatma diskriminant diýlip atlandyrylýar."}, {"kind": "match", "prompt": "Aňlatmalary manysy bilen gabat getiriň.", "points": 3, "payload": {"left": [{"id": "l1", "text": "−b / (2a)"}, {"id": "l2", "text": "b² − 4ac"}, {"id": "l3", "text": "a < 0"}], "right": [{"id": "r1", "text": "Diskriminant"}, {"id": "r2", "text": "Depe nokadynyň x koordinatasy"}, {"id": "r3", "text": "Şahalar aşak gönükdirilen"}]}, "key": {"pairs": {"l1": "r2", "l2": "r1", "l3": "r3"}}, "explanation": "Her aňlatma öz manysyna laýyk gelýär."}, {"kind": "order", "prompt": "Kwadrat deňlemäni çözmegiň ädimlerini dogry tertipde ýerleşdiriň.", "points": 3, "payload": {"items": [{"id": "i1", "text": "a, b, c koeffisiýentlerini ýazmak"}, {"id": "i2", "text": "Diskriminanty hasaplamak"}, {"id": "i3", "text": "Kökleriň formulasyny ulanmak"}, {"id": "i4", "text": "Jogaby barlamak"}]}, "key": {"order": ["i1", "i2", "i3", "i4"]}, "explanation": "Ilki koeffisiýentler, soň diskriminant, soň kökler, iň soňunda barlag."}, {"kind": "open", "prompt": "a parametriniň üýtgemegi parabolanyň görnüşine nähili täsir edýär? Mysal bilen düşündiriň.", "points": 4, "hint": "Interaktiw görkezmedäki a süýşürijisini synap görüň.", "explanation": "Garaşylýan jogap: a-nyň alamaty şahalaryň ugruny, moduly bolsa parabolanyň inçeligini kesgitleýär."}, {"kind": "practical", "prompt": "Interaktiw görkezmede a = −1, b = 2, c = 3 goýuň. Depe nokadyny, diskriminanty we kökleri ýazyň.", "points": 4, "explanation": "Garaşylýan netije: depe (1; 4), D = 16, kökler x₁ = −1, x₂ = 3."}]}, {"subject": "fizika", "title": "Om kanuny we elektrik zynjyry", "topic": "Elektrik togy", "goal": "Okuwçy Om kanunyny ulanyp tok güýjüni, naprýaženiýäni we kuwwaty hasaplap bilmeli.", "body": "**Om kanuny** zynjyryň bölegi üçin: I = U / R.\n\nBu ýerde I — tok güýji (amper, A), U — naprýaženiýe (wolt, V), R — garşylyk (om, Ω).\n\nNaprýaženiýe artsa tok güýji artýar, garşylyk artsa tok güýji kemelýär.\n\n**Kuwwat** P = U · I formulasy bilen hasaplanýar we watt (Wt) bilen ölçenýär.", "demo_kind": "circuit", "demo_config": {"u": 12, "r": 6}, "practical": "Interaktiw zynjyrda U = 24 V, R = 8 Ω goýuň. Tok güýjüni we kuwwaty ýazyň. Soňra garşylygy iki esse artdyryp, lampanyň ýagtylygynyň näme üçin üýtgändigini düşündiriň.", "test_title": "Om kanuny — barlag", "duration": 900, "questions": [{"kind": "choice", "prompt": "Om kanuny nähili ýazylýar?", "points": 1, "payload": {"options": [{"id": "a", "text": "I = U · R"}, {"id": "b", "text": "I = U / R"}, {"id": "c", "text": "U = I / R"}, {"id": "d", "text": "R = I · U"}]}, "key": {"correct": ["b"]}, "explanation": "Zynjyryň bölegi üçin Om kanuny: I = U / R."}, {"kind": "numeric", "prompt": "U = 12 V, R = 4 Ω bolsa, tok güýjüni tapyň.", "points": 2, "payload": {"unit": "A"}, "key": {"value": 3, "tolerance": 0.01, "unit": "A"}, "hint": "I = U / R", "explanation": "I = 12 / 4 = 3 A."}, {"kind": "numeric", "prompt": "I = 2 A, R = 5 Ω bolsa, naprýaženiýäni tapyň.", "points": 2, "payload": {"unit": "V"}, "key": {"value": 10, "tolerance": 0.01, "unit": "V"}, "hint": "U = I · R", "explanation": "U = 2 · 5 = 10 V."}, {"kind": "choice", "prompt": "Naprýaženiýe üýtgemän, garşylyk artsa, tok güýji nähili üýtgeýär?", "points": 1, "payload": {"options": [{"id": "a", "text": "Artýar"}, {"id": "b", "text": "Kemelýär"}, {"id": "c", "text": "Üýtgemeýär"}, {"id": "d", "text": "Nola deň bolýar"}]}, "key": {"correct": ["b"]}, "explanation": "I = U / R: R artanda I kemelýär."}, {"kind": "short", "prompt": "Tok güýjüniň ölçeg birligi nähili atlandyrylýar?", "points": 1, "key": {"accept": ["amper", "A", "amper (A)"]}, "explanation": "Tok güýji amper (A) bilen ölçenýär."}, {"kind": "choice", "prompt": "P = U · I formulasy nämäni hasaplaýar?", "points": 1, "payload": {"options": [{"id": "a", "text": "Garşylygy"}, {"id": "b", "text": "Energiýany"}, {"id": "c", "text": "Kuwwaty"}, {"id": "d", "text": "Wagty"}]}, "key": {"correct": ["c"]}, "explanation": "Bu formula elektrik kuwwatyny hasaplaýar."}, {"kind": "match", "prompt": "Fiziki ululyklary ölçeg birlikleri bilen gabat getiriň.", "points": 4, "payload": {"left": [{"id": "l1", "text": "Naprýaženiýe"}, {"id": "l2", "text": "Tok güýji"}, {"id": "l3", "text": "Garşylyk"}, {"id": "l4", "text": "Kuwwat"}], "right": [{"id": "r1", "text": "Amper (A)"}, {"id": "r2", "text": "Wolt (V)"}, {"id": "r3", "text": "Watt (Wt)"}, {"id": "r4", "text": "Om (Ω)"}]}, "key": {"pairs": {"l1": "r2", "l2": "r1", "l3": "r4", "l4": "r3"}}, "explanation": "Her ululygyň öz ölçeg birligi bar."}, {"kind": "order", "prompt": "Tok güýjüni ölçemegiň ädimlerini dogry tertipde goýuň.", "points": 3, "payload": {"items": [{"id": "i1", "text": "Zynjyry ýygnamak"}, {"id": "i2", "text": "Ampermetri yzygiderli birikdirmek"}, {"id": "i3", "text": "Çeşmäni işe girizmek"}, {"id": "i4", "text": "Görkezijini ýazyp almak"}]}, "key": {"order": ["i1", "i2", "i3", "i4"]}, "explanation": "Ampermetr hemişe yzygiderli birikdirilýär."}, {"kind": "open", "prompt": "Garşylyk artanda lampanyň ýagtylygy näme üçin peselýär? Formulalar bilen düşündiriň.", "points": 4, "hint": "I we P formulalaryny bilelikde ulanyň.", "explanation": "Garaşylýan jogap: R artanda I = U/R kemelýär, şoňa görä P = U·I hem kemelýär we lampa az ýagtylyk berýär."}, {"kind": "practical", "prompt": "Interaktiw zynjyrda U = 24 V, R = 8 Ω goýuň. Tok güýjüni we kuwwaty ýazyň.", "points": 4, "explanation": "Garaşylýan netije: I = 3 A, P = 72 Wt."}]}, {"subject": "himiya", "title": "Himiki reaksiýalary deňlemek", "topic": "Himiki deňlemeler", "goal": "Okuwçy massanyň saklanyş kanunyna esaslanyp, reaksiýanyň koeffisiýentlerini saýlap bilmeli.", "body": "**Massanyň saklanyş kanuny** boýunça reaksiýa girýän maddalaryň massasy, emele gelýän maddalaryň massasyna deňdir.\n\nŞonuň üçin deňlemäniň çep we sag tarapynda her elementiň atom sany **deň** bolmalydyr.\n\nDeňlemek üçin **koeffisiýentler** saýlanýar. Indeksleri üýtgetmek bolmaýar — ol maddanyň özüni üýtgedýär.\n\nMysal: 2H₂ + O₂ → 2H₂O. Çepde 4 H we 2 O, sagda 4 H we 2 O.", "demo_kind": "reaction", "demo_config": {"left": [{"f": "H₂", "atoms": {"H": 2}}, {"f": "O₂", "atoms": {"O": 2}}], "right": [{"f": "H₂O", "atoms": {"H": 2, "O": 1}}]}, "practical": "Interaktiw görkezmede H₂ + O₂ → H₂O reaksiýasyny deňläň. Saýlan koeffisiýentleriňizi we her elementiň atom sanyny ýazyň.", "test_title": "Himiki deňlemeler — barlag", "duration": 900, "questions": [{"kind": "choice", "prompt": "Reaksiýany deňlemek haýsy kanuna esaslanýar?", "points": 1, "payload": {"options": [{"id": "a", "text": "Om kanunyna"}, {"id": "b", "text": "Massanyň saklanyş kanunyna"}, {"id": "c", "text": "Arhimed kanunyna"}, {"id": "d", "text": "Nýutonyň kanunyna"}]}, "key": {"correct": ["b"]}, "explanation": "Deňlemek massanyň saklanyş kanunyna esaslanýar."}, {"kind": "choice", "prompt": "Deňlemegiň dowamynda nämäni üýtgetmek bolýar?", "points": 2, "payload": {"options": [{"id": "a", "text": "Diňe koeffisiýentleri"}, {"id": "b", "text": "Diňe indeksleri"}, {"id": "c", "text": "Koeffisiýentleri we indeksleri"}, {"id": "d", "text": "Hiç zady"}]}, "key": {"correct": ["a"]}, "explanation": "Indeks üýtgese madda başga madda öwrülýär, şonuň üçin diňe koeffisiýent saýlanýar."}, {"kind": "numeric", "prompt": "2H₂ + O₂ → 2H₂O reaksiýasynda çep tarapda näçe wodorod atomy bar?", "points": 2, "key": {"value": 4, "tolerance": 0}, "hint": "2 × H₂ = ?", "explanation": "2 molekula × 2 atom = 4 wodorod atomy."}, {"kind": "numeric", "prompt": "Fe + O₂ → Fe₂O₃ reaksiýasyny deňläniňizde Fe-niň öňündäki koeffisiýent näçe bolýar?", "points": 3, "key": {"value": 4, "tolerance": 0}, "hint": "Deňlenen görnüşi: 4Fe + 3O₂ → 2Fe₂O₃", "explanation": "Dogry deňleme: 4Fe + 3O₂ → 2Fe₂O₃."}, {"kind": "short", "prompt": "H₂O maddasynyň türkmençe ady näme?", "points": 1, "key": {"accept": ["suw"]}, "explanation": "H₂O — suw."}, {"kind": "match", "prompt": "Formulalary maddalaryň atlary bilen gabat getiriň.", "points": 4, "payload": {"left": [{"id": "l1", "text": "H₂O"}, {"id": "l2", "text": "CO₂"}, {"id": "l3", "text": "NaCl"}, {"id": "l4", "text": "O₂"}], "right": [{"id": "r1", "text": "Kömürturşy gazy"}, {"id": "r2", "text": "Nahar duzy"}, {"id": "r3", "text": "Suw"}, {"id": "r4", "text": "Kislorod"}]}, "key": {"pairs": {"l1": "r3", "l2": "r1", "l3": "r2", "l4": "r4"}}, "explanation": "Her formula öz maddasyna degişlidir."}, {"kind": "order", "prompt": "Reaksiýany deňlemegiň ädimlerini dogry tertipde goýuň.", "points": 3, "payload": {"items": [{"id": "i1", "text": "Reaksiýanyň shemasyny ýazmak"}, {"id": "i2", "text": "Her elementiň atom sanyny sanamak"}, {"id": "i3", "text": "Koeffisiýentleri saýlamak"}, {"id": "i4", "text": "Iki tarapy deňeşdirip barlamak"}]}, "key": {"order": ["i1", "i2", "i3", "i4"]}, "explanation": "Ilki shema, soň sanamak, soň koeffisiýent, iň soňunda barlag."}, {"kind": "choice", "prompt": "2H₂ + O₂ → 2H₂O — bu haýsy görnüşli reaksiýa?", "points": 2, "payload": {"options": [{"id": "a", "text": "Birleşme reaksiýasy"}, {"id": "b", "text": "Dargama reaksiýasy"}, {"id": "c", "text": "Çalyşma reaksiýasy"}, {"id": "d", "text": "Alyş-çalyş reaksiýasy"}]}, "key": {"correct": ["a"]}, "explanation": "Iki madda birleşip bir madda emele getirýär."}, {"kind": "open", "prompt": "Näme üçin deňlemekde indeksleri däl-de, koeffisiýentleri üýtgetmeli? Düşündiriň.", "points": 4, "explanation": "Garaşylýan jogap: indeks maddanyň düzümini görkezýär; ony üýtgetsek başga madda alarys. Koeffisiýent bolsa diňe molekulalaryň sanyny görkezýär."}, {"kind": "practical", "prompt": "Interaktiw görkezmede H₂ + O₂ → H₂O reaksiýasyny deňläň we koeffisiýentleriňizi ýazyň.", "points": 4, "explanation": "Garaşylýan netije: 2H₂ + O₂ → 2H₂O."}]}, {"subject": "biologiya", "title": "Öýjügiň gurluşy we organoidleri", "topic": "Öýjük", "goal": "Okuwçy öýjügiň esasy bölekleri tanap, olaryň wezipesini düşündirip bilmeli.", "body": "**Öýjük** — janly organizmiň gurluş we wezipe birligidir.\n\n**Ýadro** nesil maglumatyny saklaýar we öýjügiň işini dolandyrýar.\n\n**Mitohondriýa** energiýa (ATF) öndürýär, şonuň üçin oňa öýjügiň «elektrik stansiýasy» diýilýär.\n\n**Ribosoma** belok sintezini amala aşyrýar. **Wakuola** suw we iýmit maddalaryny saklaýar. **Membrana** öýjügi gorap, madda alyş-çalşyny sazlaýar.", "demo_kind": "cell", "demo_config": {}, "practical": "Interaktiw görkezmede öýjügiň üç bölegine basyň. Olaryň atlaryny we wezipelerini öz sözleriňiz bilen ýazyň.", "test_title": "Öýjügiň gurluşy — barlag", "duration": 900, "questions": [{"kind": "choice", "prompt": "Öýjükde nesil maglumatyny haýsy organoid saklaýar?", "points": 1, "payload": {"options": [{"id": "a", "text": "Ribosoma"}, {"id": "b", "text": "Wakuola"}, {"id": "c", "text": "Ýadro"}, {"id": "d", "text": "Membrana"}]}, "key": {"correct": ["c"]}, "explanation": "Nesil maglumaty ýadroda saklanýar."}, {"kind": "short", "prompt": "Öýjükde energiýa öndürýän organoidiň ady näme?", "points": 2, "key": {"accept": ["mitohondriýa", "mitohondriya", "mitohondriýalar"]}, "hint": "Oňa öýjügiň elektrik stansiýasy diýilýär.", "explanation": "Mitohondriýa ATF görnüşinde energiýa öndürýär."}, {"kind": "choice", "prompt": "Belok sintezi haýsy organoidde amala aşyrylýar?", "points": 2, "payload": {"options": [{"id": "a", "text": "Ribosomada"}, {"id": "b", "text": "Ýadroda"}, {"id": "c", "text": "Wakuolada"}, {"id": "d", "text": "Membranada"}]}, "key": {"correct": ["a"]}, "explanation": "Belok sintezi ribosomada geçýär."}, {"kind": "choice", "prompt": "Öýjük membranasynyň esasy wezipesi näme?", "points": 2, "payload": {"options": [{"id": "a", "text": "Energiýa öndürmek"}, {"id": "b", "text": "Madda alyş-çalşyny sazlamak"}, {"id": "c", "text": "Belok sintezi"}, {"id": "d", "text": "Nesil maglumatyny saklamak"}]}, "key": {"correct": ["b"]}, "explanation": "Membrana öýjügi gorap, madda geçişini sazlaýar."}, {"kind": "match", "prompt": "Organoidleri wezipeleri bilen gabat getiriň.", "points": 4, "payload": {"left": [{"id": "l1", "text": "Ýadro"}, {"id": "l2", "text": "Mitohondriýa"}, {"id": "l3", "text": "Ribosoma"}, {"id": "l4", "text": "Wakuola"}], "right": [{"id": "r1", "text": "Energiýa öndürmek"}, {"id": "r2", "text": "Belok sintezi"}, {"id": "r3", "text": "Nesil maglumatyny saklamak"}, {"id": "r4", "text": "Suw we iýmit saklamak"}]}, "key": {"pairs": {"l1": "r3", "l2": "r1", "l3": "r2", "l4": "r4"}}, "explanation": "Her organoidiň anyk wezipesi bar."}, {"kind": "order", "prompt": "Janly tebigatyň gurluş derejelerini kiçiden ula tertipde goýuň.", "points": 3, "payload": {"items": [{"id": "i1", "text": "Öýjük"}, {"id": "i2", "text": "Dokuma"}, {"id": "i3", "text": "Organ"}, {"id": "i4", "text": "Organizm"}]}, "key": {"order": ["i1", "i2", "i3", "i4"]}, "explanation": "Öýjük → dokuma → organ → organizm."}, {"kind": "numeric", "prompt": "Interaktiw görkezmede öýjügiň näçe bölegi bellenen?", "points": 2, "key": {"value": 5, "tolerance": 0}, "hint": "Görkezmedäki tegelekleri sanaň.", "explanation": "Bellenen bölekleriň sany — 5."}, {"kind": "choice", "prompt": "Haýsy organoid diňe ösümlik öýjügine mahsusdyr?", "points": 2, "payload": {"options": [{"id": "a", "text": "Ýadro"}, {"id": "b", "text": "Mitohondriýa"}, {"id": "c", "text": "Hloroplast"}, {"id": "d", "text": "Ribosoma"}]}, "key": {"correct": ["c"]}, "explanation": "Hloroplast fotosintez geçirýär we diňe ösümlik öýjüginde bolýar."}, {"kind": "open", "prompt": "Ösümlik we haýwan öýjükleriniň esasy tapawutlaryny ýazyň.", "points": 4, "explanation": "Garaşylýan jogap: ösümlik öýjüginde öýjük diwary, hloroplast we uly wakuola bar; haýwan öýjüginde olar ýok."}, {"kind": "practical", "prompt": "Interaktiw görkezmede üç bölege basyp, atlaryny we wezipelerini ýazyň.", "points": 4, "explanation": "Garaşylýan netije: islendik üç organoid dogry at we wezipe bilen."}]}, {"subject": "informatika", "title": "Tertipleşdirme algoritmi", "topic": "Algoritmler", "goal": "Okuwçy köpürjik tertipleşdirmesiniň ädimlerini yzarlap, deňeşdirmeleriň sanyny hasaplap bilmeli.", "body": "**Algoritm** — meseläni çözmegiň anyk we yzygiderli ädimleri.\n\n**Köpürjik tertipleşdirmesi** (bubble sort) goňşy elementleri deňeşdirip, zerur bolsa olary çalyşýar. Her geçişde iň uly element sanawyň soňuna «ýüzüp çykýar».\n\nn element üçin iň erbet ýagdaýda deňeşdirmeleriň sany: n · (n − 1) / 2.\n\nBu algoritm düşnükli, ýöne uly maglumatlar üçin haýal işleýär.", "demo_kind": "algorithm", "demo_config": {"array": [5, 2, 9, 1, 7, 3]}, "practical": "Interaktiw görkezmede «Ädim» düwmesine basyp, algoritmi ahyryna çenli ýerine ýetiriň. Deňeşdirmeleriň we çalyşmalaryň sanyny ýazyň.", "test_title": "Algoritmler — barlag", "duration": 900, "questions": [{"kind": "choice", "prompt": "Köpürjik tertipleşdirmesi näme edýär?", "points": 1, "payload": {"options": [{"id": "a", "text": "Elementleri tötänleýin garyşdyrýar"}, {"id": "b", "text": "Goňşy elementleri deňeşdirip çalyşýar"}, {"id": "c", "text": "Sanawy ikä bölýär"}, {"id": "d", "text": "Iň uly elementi pozýar"}]}, "key": {"correct": ["b"]}, "explanation": "Goňşy elementler deňeşdirilýär we zerur bolsa çalşylýar."}, {"kind": "numeric", "prompt": "6 element üçin iň erbet ýagdaýda näçe deňeşdirme gerek?", "points": 3, "key": {"value": 15, "tolerance": 0}, "hint": "n · (n − 1) / 2", "explanation": "6 · 5 / 2 = 15."}, {"kind": "short", "prompt": "Meseläni çözmegiň anyk we yzygiderli ädimleri nähili atlandyrylýar?", "points": 1, "key": {"accept": ["algoritm", "algoritm diýilýär"]}, "explanation": "Bu düşünje algoritm diýlip atlandyrylýar."}, {"kind": "order", "prompt": "Köpürjik tertipleşdirmesiniň ädimlerini dogry tertipde goýuň.", "points": 3, "payload": {"items": [{"id": "i1", "text": "Birinji we ikinji elementi deňeşdirmek"}, {"id": "i2", "text": "Zerur bolsa olary çalyşmak"}, {"id": "i3", "text": "Indiki jübüte geçmek"}, {"id": "i4", "text": "Çalyşma galmasa durmak"}]}, "key": {"order": ["i1", "i2", "i3", "i4"]}, "explanation": "Deňeşdir → çalyş → indiki jübüt → çalyşma ýok bolsa dur."}, {"kind": "choice", "prompt": "Algoritmiň haýsy häsiýeti onuň çäkli sanly ädimde gutarmalydygyny aňladýar?", "points": 2, "payload": {"options": [{"id": "a", "text": "Köpçülikleýinlik"}, {"id": "b", "text": "Düşnüklilik"}, {"id": "c", "text": "Netijelilik"}, {"id": "d", "text": "Diskretlik"}]}, "key": {"correct": ["c"]}, "explanation": "Netijelilik algoritmiň çäkli ädimde netije bermegini talap edýär."}, {"kind": "match", "prompt": "Düşünjeleri kesgitlemeleri bilen gabat getiriň.", "points": 3, "payload": {"left": [{"id": "l1", "text": "Massiw"}, {"id": "l2", "text": "Sikl"}, {"id": "l3", "text": "Şert"}], "right": [{"id": "r1", "text": "Saýlawy kesgitleýän aňlatma"}, {"id": "r2", "text": "Bir görnüşli elementleriň tertipli toplumy"}, {"id": "r3", "text": "Gaýtalanýan ädimler"}]}, "key": {"pairs": {"l1": "r2", "l2": "r3", "l3": "r1"}}, "explanation": "Her düşünje öz kesgitlemesine laýyk gelýär."}, {"kind": "numeric", "prompt": "[5, 2, 9] massiwinde birinji geçişde näçe çalyşma bolar?", "points": 2, "key": {"value": 1, "tolerance": 0}, "hint": "5 we 2 deňeşdirilende näme bolýar?", "explanation": "5 > 2 — çalyşma bolýar. 5 < 9 — çalyşma ýok. Jemi 1 çalyşma."}, {"kind": "choice", "prompt": "Köpürjik tertipleşdirmesiniň esasy kemçiligi näme?", "points": 2, "payload": {"options": [{"id": "a", "text": "Ýalňyş netije berýär"}, {"id": "b", "text": "Uly maglumatlar üçin haýal işleýär"}, {"id": "c", "text": "Diňe sanlar bilen işleýär"}, {"id": "d", "text": "Köp ýat talap edýär"}]}, "key": {"correct": ["b"]}, "explanation": "Algoritm düşnükli, ýöne n uly bolanda haýal işleýär."}, {"kind": "open", "prompt": "Köpürjik tertipleşdirmesiniň işleýşini öz sözleriňiz bilen düşündiriň.", "points": 4, "hint": "Interaktiw görkezmäni ulanyp synap görüň.", "explanation": "Garaşylýan jogap: goňşy elementler deňeşdirilýär, uly element öňe geçse çalşylýar, her geçişde iň uly element soňuna süýşýär."}, {"kind": "practical", "prompt": "Interaktiw görkezmäni ahyryna çenli işlediň we deňeşdirmeleriň we çalyşmalaryň sanyny ýazyň.", "points": 4, "explanation": "Garaşylýan netije: [5,2,9,1,7,3] üçin deňeşdirme 15, çalyşma 9."}]}]'::jsonb;
  v_teacher bigint;
  blk jsonb; q jsonb;
  v_subject bigint; v_lesson bigint; v_test bigint; v_q bigint; pos int;
begin
  if exists (select 1 from lessons) then
    return;
  end if;

  select id into v_teacher from teachers order by id limit 1;
  if v_teacher is null then
    return;
  end if;

  for blk in select * from jsonb_array_elements(v_data) loop
    select id into v_subject from subjects where code = blk->>'subject';
    continue when v_subject is null;

    insert into lessons (teacher_id, subject_id, title, topic, goal, body_md,
                         demo_kind, demo_config, practical_task)
    values (v_teacher, v_subject, blk->>'title', blk->>'topic', blk->>'goal',
            blk->>'body', blk->>'demo_kind', blk->'demo_config', blk->>'practical')
    returning id into v_lesson;

    insert into tests (teacher_id, subject_id, title, duration_sec, results_policy)
    values (v_teacher, v_subject, blk->>'test_title', (blk->>'duration')::int, 'after_close')
    returning id into v_test;

    pos := 0;
    for q in select * from jsonb_array_elements(blk->'questions') loop
      pos := pos + 1;
      insert into questions (lesson_id, subject_id, kind, prompt, payload, answer_key,
                             points, hint, explanation, position)
      values (v_lesson, v_subject, q->>'kind', q->>'prompt',
              coalesce(q->'payload', '{}'::jsonb), coalesce(q->'key', '{}'::jsonb),
              coalesce((q->>'points')::numeric, 1), coalesce(q->>'hint', ''),
              coalesce(q->>'explanation', ''), pos)
      returning id into v_q;

      insert into test_questions (test_id, question_id, position)
      values (v_test, v_q, pos);
    end loop;
  end loop;
end $$;
